WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( EXISTS (SELECT 1 FROM "public"."article" AS "e0" WHERE true AND "e0"."author_id" = "s"."id" AND ( EXISTS (SELECT 1 FROM "public"."comment" AS "e1" WHERE true AND "e1"."article_id" = "e0"."id" AND ( "e1"."body" ILIKE $1 )) )) ) ORDER BY "s"."id" ASC NULLS LAST ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0"
